head.script:
scwin.onpageunload = function() {};
scwin.trigger1_onclick = function(e) {
    comLib.fn_test("Tetfcewfwf");
};
scwin.unitTest = function() {
    //init
    WebSquare.wUnit.start();
    WebSquare.wUnit.addCommand("pause", "1000");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger1').click()");
    WebSquare.wUnit.addCommand("pause", "1500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('popup1_wframe_trigger2').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('popup1_wframe_trigger1').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "localStorage.getItem('log') == 'bbbb = 손예진'", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "localStorage.removeItem('log')");
    WebSquare.wUnit.addCommand("pause", "500");
    //Run  and stop
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.unitTest();
scwin.onpageload = function() {
    /**
     * @target
     */
    window.comLib = {}; //This is WebSquare JavaScript Marker. Do not remove this line.
    comLib.fn_test = function(a) {
        comLib.fn_F_TEST(a);
    };
    comLib.fn_F_TEST = function(a) {
        console.log("aaaa = " + a)
        if(WebSquare._xv !== "SP5"){requires("uiplugin.popup");}
        window.rowJSON = {
            "addr": "서울시",
            "name": "손예진",
            "rowStatus": "R"
        };
        //popup에 넘길 data객체. 
        window.dataObj = {
            type: "json", // 데이터 타입. "xml","string","json","array" 
            data: rowJSON, // 전달 데이터 객체. 
            name: "paramTest" // 변수명. popup에서 $w.getParameter( "paramTest" )로 깨내올 수 있다. 
        };
        window.options = {
            id: "popup1",
            type: "wframePopup",
            width: 700 + "px",
            height: 400 + "px",
            top: 100 + "px",
            left: 100 + "px",
            popupName: "Test111",
            modal: true,
            style: "",
            resizable: true,
            status: false,
            menubar: false,
            scrollbars: false,
            title: false,
            useMaximize: true,
            dataObject: dataObj
        };
        $p.openPopup("wframeOpup_getparameter_WEFF-599_(WSQ-3961)_sub_auto.xml", options);
    };
}
